input.mermaid:
graph TD
    A[Start/Current State Q] --> B{Clock Edge Triggered?};
    B -- No --> C[Output remains unchanged (Q)];
    B -- Yes --> D{J and K values?};
    D -- J=0, K=0 --> E[Hold State (Q remains same)];
    D -- J=1, K=0 --> F[Set State (Q becomes 1)];
    D -- J=0, K=1 --> G[Reset State (Q becomes 0)];
    D -- J=1, K=1 --> H[Toggle State (Q becomes NOT Q)];
    E --> I[New State Q];
    F --> I;
    G --> I;
    H --> I;

graph TD
    A[Start: Root Node] --> B{Select best split based on feature importance};
    B --> C{Is the resulting node a leaf node?};
    C -- No --> D[Split Data into subsets];
    D --> E{Evaluate entropy/Gini index for subsets};
    E --> F[Create new child nodes];
    F --> G{Check for purity in subsets};
    G -- No --> B;
    G -- Yes --> H[Node becomes a Leaf Node (Classification)];
    C -- Yes --> H;
    H --> I[End];
